import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

max_reduce_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <vector>
#include <float.h>

__global__ void max_reduce_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int64_t outer_size,
    int64_t reduce_size,
    int64_t inner_size,
    int64_t vec_count,
    int64_t remainder)
{
    int64_t outer_idx = blockIdx.y;
    if (outer_idx >= outer_size) return;
    int64_t idx = blockIdx.x * (int64_t)blockDim.x + threadIdx.x;
    int64_t total_work = vec_count + remainder;
    if (idx >= total_work) return;
    if (idx < vec_count) {
        int64_t inner_start = idx * 4;
        const float* base = input + outer_idx * reduce_size * inner_size + inner_start;
        float4 max_vec = make_float4(-FLT_MAX, -FLT_MAX, -FLT_MAX, -FLT_MAX);
        #pragma unroll 4
        for (int64_t k = 0; k < reduce_size; ++k) {
            float4 v = __ldg(reinterpret_cast<const float4*>(base + k * inner_size));
            max_vec.x = fmaxf(max_vec.x, v.x);
            max_vec.y = fmaxf(max_vec.y, v.y);
            max_vec.z = fmaxf(max_vec.z, v.z);
            max_vec.w = fmaxf(max_vec.w, v.w);
        }
        float* out_base = output + outer_idx * inner_size + inner_start;
        reinterpret_cast<float4*>(out_base)[0] = max_vec;
    } else {
        int64_t inner_idx = vec_count * 4 + (idx - vec_count);
        const float* base = input + outer_idx * reduce_size * inner_size + inner_idx;
        float max_val = -FLT_MAX;
        #pragma unroll 4
        for (int64_t k = 0; k < reduce_size; ++k) {
            float val = __ldg(&base[k * inner_size]);
            max_val = fmaxf(max_val, val);
        }
        output[outer_idx * inner_size + inner_idx] = max_val;
    }
}
torch::Tensor max_reduce_cuda(torch::Tensor input, int64_t dim) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    int64_t ndim = input.dim();
    if (dim < 0) dim += ndim;
    TORCH_CHECK(dim >= 0 && dim < ndim, "dim out of range");
    auto sizes = input.sizes();
    int64_t outer_size = 1;
    for (int64_t i = 0; i < dim; ++i) outer_size *= sizes[i];
    int64_t reduce_size = sizes[dim];
    int64_t inner_size = 1;
    for (int64_t i = dim + 1; i < ndim; ++i) inner_size *= sizes[i];
    std::vector<int64_t> out_sizes;
    for (int64_t i = 0; i < ndim; ++i) {
        if (i != dim) out_sizes.push_back(sizes[i]);
    }
    auto output = torch::empty(out_sizes, input.options());
    int threads = 256;
    int64_t vec_count = (inner_size % 4 == 0) ? (inner_size / 4) : 0;
    int64_t remainder = inner_size - vec_count * 4;
    int64_t work_count = vec_count + remainder;
    int64_t blocks_x = (work_count + threads - 1) / threads;
    if (blocks_x < 1) blocks_x = 1;
    int64_t blocks_y = outer_size;
    if (blocks_y < 1) blocks_y = 1;
    dim3 grid((unsigned int)blocks_x, (unsigned int)blocks_y);
    dim3 block(threads);
    max_reduce_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        outer_size,
        reduce_size,
        inner_size,
        vec_count,
        remainder
    );
    return output;
}
"""

max_reduce_header = r"""
torch::Tensor max_reduce_cuda(torch::Tensor input, int64_t dim);
"""

max_reduce_module = load_inline(
    name="max_reduce_module",
    cpp_sources=max_reduce_header,
    cuda_sources=max_reduce_source,
    functions=["max_reduce_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs Max reduction over a specific dimension
    using a custom CUDA kernel.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous().cuda()
        return max_reduce_module.max_reduce_cuda(x, self.dim)

